l":null,"isTender":false,"isSaudiSpecific":true,"evidence":{"officialContentVerified":true,"actionLinkedFromOfficial":true,"actionLandingFetched":true,"formSubmissionTested":false,"method":"TinyFish free search/fetch_content","checkedAt":"2026-10-09T13:13:00Z","httpsRouteSeparatelyFetched":true},"source_id":"aramco","kind":"supplier_registration","registration_verified":true,"verification_method":"Verified official public extraction; manual import","last_verified":"2026-10-09T13:16:00Z","organization":"أرامكو السعودية","organization_en":"Saudi Aramco","title_en":"Saudi Aramco supplier registration","description_en":"Registration for materials and service providers based in Saudi Arabia through e-Marketplace. Registration and qualification do not guarantee future business.","source_url":"https://www.aramco.com/en/what-we-do/suppliers/become-a-supplier","login_required":true,"documents":["السجل التجاري","شهادة الزكاة","شهادة ضريبة القيمة المضافة","التأمينات الاجتماعية","عضوية الغرفة التجارية","تصنيف المقاول عند انطباقه","إقرار مدونة سلوك الموردين","خطاب البنك","ملف ملكية الشركة","خطاب المفوض بالتوقيع","شهادة الامتثال للأمن السيبراني CCC"],"published_at":null,"apply_url":null,"registration_url":"https://aramco-e-marketplace.sourcing.mn2.ariba.com/ad/selfRegistration"}', '2026-10-09T13:16:00Z', '2026-10-10T23:53:28.303Z');
