,"formSubmissionTested":false,"method":"TinyFish free search/fetch_content","checkedAt":"2026-10-09T13:13:00Z"},"source_id":"rsg","kind":"supplier_registration","registration_verified":true,"verification_method":"Verified official public extraction; manual import","last_verified":"2026-10-09T13:13:00Z","organization":"البحر الأحمر العالمية","organization_en":"Red Sea Global","title_en":"Red Sea Global supplier interest registration","description_en":"Supplier interest form. RSG reviews capabilities and categories, contacts suitable businesses, then progresses formal registration. It is not a tender application.","source_url":"https://www.redseaglobal.com/en/vendor-registration/","login_required":false,"documents":["بيانات الشركة","فئات المنتجات أو الخدمات","مدونة سلوك الموردين في مرحلة التسجيل الرسمي"],"published_at":null,"apply_url":null,"registration_url":"https://www.redseaglobal.com/en/vendor-registration/#form-v2"}', '2026-10-09T13:13:00Z', '2026-10-10T23:53:28.303Z');
