INSERT OR REPLACE INTO opportunities (id, fingerprint, source_id, kind, status, deadline, title, city, organization, data, created_at, updated_at) VALUES ('supplier-diriyah', '70a377d9c518f5137ac39d7b50b8f4631dac16d7f2e082749d35a6dacf75b1e9', 'diriyah', 'supplier_registration', 'registration_available', NULL, 'بوابة تسجيل الموردين لشركة الدرعية', 'الدرعية', 'شركة الدرعية', '{"id":"supplier-diriyah","type":"SUPPLIER_REGISTRATION","title":"بوابة تسجيل الموردين لشركة الدرعية","titleEn":"Diriyah Company vendor registration","issuer":"شركة الدرعية","issuerEn":"Diriyah Company","city":"الدرعية","country":"SA","sectors":["construction","supplies","manpower","facilities","logistics","services"],"description":"طلب تسجيل ثم استبيان تسجيل وتأهيل حسب الفئات. الفئات المعلنة تشمل أعمال البناء والبنية التحتية وFF&E وخدمات رأس المال البشري وإدارة الأصول والنقل. التسجيل لدى هيئة تطوير بوابة الدرعية منفصل عن شركة الدرعية.","descriptionEn":"Registration request, followed by registration and category qualification questionnaires. Published categories include building/infrastructure, FF&E, human capital, asset management and mobility. DGDA registration is separate from Diriyah Company.","sourceUrl":"https://www.diriyahcompany.sa/en/vendor-register","actionUrl":"https://dgda.sourcing.ksaprv.cloud.ariba.com/ad/selfRegistration","actionType":"register","actionLabel":"تسجيل كمورد","loginRequired":true,"accountRequired":true,"status":"registration_available","deadline":null,"publishedAt":null,"lastVerifiedAt":"2026-10-09T13:13:00Z","sourceStatus":"MANUAL_IMPORT","publicAccess":"LIVE","actionAccess":"DEGRADED","confidence":91,"confidenceScope":"Official page and linked onboarding route verified; form submission, approval and tender invitation not tested.","requiredDocuments":["الاستبيان","المستندات الداعمة المطلوبة في مرحلة التأهيل"],"verificationNote":"الرابط الرسمي يحمل اسم DGDA لكنه وصلت منه صفحة بعنوان Welcome to Diriyah Company Ariba portal. استخراج النموذج ناقص؛ لم يرسل أي طلب.","applicationUrl":null,"isTender":false,"isSaudiSpecific":true,"evidence":{"officialContentVerified":true,"actionLinkedFromOfficial":true,"actionLandingFetched":true,"formSubmissionTested":false,"method":"TinyFish free search/fetch_content","checkedAt":"2026-10-09T13:13:00Z"},"source_id":"diriyah","kind":"supplier_registration","registration_verified":true,"verification_method":"Verified official public extraction; manual import","last_verified":"2026-10-09T13:13:00Z","organization":"شركة الدرعية","organization_en":"Diriyah Company","title_en":"Diriyah Company vendor registration","description_en":"Registration request, followed by registration and category qualification questionnaires. Published categories include building/infrastructure, FF&E, human capital, asset management and mobility. DGDA registration is separate from Diriyah Company.","source_url":"https://www.diriyahcompany.sa/en/vendor-register","login_required":true,"documents":["الاستبيان","المستندات الداعمة المطلوبة في مرحلة التأهيل"],"published_at":null,"apply_url":null,"registration_url":"https://dgda.sourcing.ksaprv.cloud.ariba.com/ad/selfRegistration"}', '2026-10-09T13:13:00Z', '2026-10-10T23:53:28.303Z');
INSERT OR REPLACE INTO opportunities (id, fingerprint, source_id, kind, status, deadline, title, city, organization, data, created_at, updated_at) VALUES ('supplier-psfm', '9b0961ac31a8a3746dd8a34aa3380f96ae471377d3dfdaf8d4f7fa36845e5c78', 'psfm', 'supplier_registration', 'registration_available', NULL, 'تسجيل موردي وشركاء الخدمات لدى PSFM السعودية', 'جدة', 'بريميوم سبورت لإدارة المرافق', '{"id":"supplier-psfm","type":"SUPPLIER_REGISTRATION","title":"تسجيل موردي وشركاء الخدمات لدى PSFM السعودية","titleEn":"PSFM Saudi supplier prequalification","issuer":"بريميوم سبورت لإدارة المرافق","issuerEn":"Premium Support Facility Management Ltd","city":"جدة","country":"SA","sectors":["manpower","housekeeping","cleaning","facilities","maintenance","construction","logistics","supplies"],"description":"نموذج تأهيل مورّد فعلي يطلب نطاق الخدمات والمدن والطاقة البشرية. فئاته تشمل توريد العمالة والتوظيف والنظافة وHousekeeping وMEP والمقاولات والمواد والمعدات واللوجستيات. لا يضمن اعتمادًا أو أمر شراء أو عقدًا.","descriptionEn":"Actual supplier prequalification form asks service scope, cities and manpower capacity. Categories include manpower/recruitment, cleaning/housekeeping, MEP, civil works, materials/equipment and logistics. It does not guarantee approval, purchase order or contract.","sourceUrl":"https://www.premium-sa.com/vendors-registration","actionUrl":"https://www.premium-sa.com/vendors-registration#vendor-registration-form","actionType":"register","actionLabel":"تسجيل كمورد","loginRequired":false,"accountRequired":false,"status":"registration_available","deadline":null,"publishedAt":null,"lastVerifiedAt":"2026-10-09T13:13:00Z","sourceStatus":"MANUAL_IMPORT","publicAccess":"LIVE","actionAccess":"LIVE","confidence":97,"confidenceScope":"Official page and linked onboarding route verified; form submission, approval and tender invitation not tested.","requiredDocuments":["ملف الشركة","السجل التجاري","خطاب البنك أو الآيبان","شهادة السعودة","هوية المالك","شهادة ضريبة القيمة المضافة اختيارية"],"verificationNote":"تم استخراج حقول النموذج نفسه. توجد صياغات متعارضة في أسئلة الصفحة بشأن كون بعض المرفقات اختيارية؛ قائمة الوثائق هنا تعتمد حقول النموذج الإلزامية الحالية. لم يُرسل أي طلب.","applicationUrl":null,"isTender":false,"isSaudiSpecific":true,"evidence":{"officialContentVerified":true,"actionLinkedFromOfficial":true,"actionLandingFetched":true,"formSubmissionTested":false,"method":"TinyFish free search/fetch_content","checkedAt":"2026-10-09T13:13:00Z"},"source_id":"psfm","kind":"supplier_registration","registration_verified":true,"verification_method":"Verified official public extraction; manual import","last_verified":"2026-10-09T13:13:00Z","organization":"بريميوم سبورت لإدارة المرافق","organization_en":"Premium Support Facility Management Ltd","title_en":"PSFM Saudi supplier prequalification","description_en":"Actual supplier prequalification form asks service scope, cities and manpower capacity. Categories include manpower/recruitment, cleaning/housekeeping, MEP, civil works, materials/equipment and logistics. It does not guarantee approval, purchase order or contract.","source_url":"https://www.premium-sa.com/vendors-registration","login_required":false,"documents":["ملف الشركة","السجل التجاري","خطاب البنك أو الآيبان","شهادة السعودة","هوية المالك","شهادة ضريبة القيمة المضافة اختيارية"],"published_at":null,"apply_url":null,"registration_url":"https://www.premium-sa.com/vendors-registration#vendor-registration-form"}', '2026-10-09T13:13:00Z', '2026-10-10T23:53:28.303Z');
INSERT OR REPLACE INTO opportunities (id, fingerprint, source_id, kind, status, deadline, title, city, organization, data, created_at, updated_at) VALUES ('supplier-ifas', 'dc16ccce6a89acdc64ad1390d524fa337d6cfba8e7327654a402fa07aa37f927', 'ifas', 'supplier_registration', 'registration_available', NULL, 'التسجيل كمورد وشريك لإدارة المرافق لدى IFAS', 'السعودية', 'IFAS لإدارة المرافق', '{"id":"supplier-ifas","type":"SUPPLIER_REGISTRATION","title":"التسجيل كمورد وشريك لإدارة المرافق لدى IFAS","titleEn":"IFAS supplier and facility-services registration","issuer":"IFAS لإدارة المرافق","issuerEn":"IFAS","city":"السعودية","country":"SA","sectors":["manpower","housekeeping","cleaning","facilities","maintenance","security","landscaping","construction","logistics"],"description":"نموذج توريد وخدمات حقيقي يضم النظافة، الأمن، تنسيق الحدائق، النفايات، توريد العمالة وHousekeeping، صيانة HVAC والكهرباء والسباكة وMEP والأعمال المدنية والتشطيبات. يُطلب التأهيل والمستندات؛ ليس مناقصة بعينها.","descriptionEn":"Actual supplier/service form includes cleaning, security, landscaping, waste, manpower/housekeeping, HVAC/electrical/plumbing/MEP maintenance and civil/fitout works. Qualification and supporting documents are requested; not a specific tender.","sourceUrl":"https://ifas-ksa.com/supplier-portal/","actionUrl":"https://ifas-ksa.com/supplier-portal/","actionType":"register","actionLabel":"تسجيل كمورد","loginRequired":false,"accountRequired":false,"status":"registration_available","deadline":null,"publishedAt":null,"lastVerifiedAt":"2026-10-09T13:13:00Z","sourceStatus":"MANUAL_IMPORT","publicAccess":"LIVE","actionAccess":"LIVE","confidence":97,"confidenceScope":"Official page and linked onboarding route verified; form submission, approval and tender invitation not tested.","requiredDocuments":["السجل التجاري","شهادة ضريبة القيمة المضافة","شهادة البنك والآيبان","عقد التأسيس","القوائم المالية لآخر 3 سنوات","تقرير المشاريع المنجزة وغير المنجزة","تقرير القضايا ونتائجها","خطاب الممثل المفوض مصدقًا من الغرفة التجارية","اتفاقية عدم إفشاء موقعة ومختومة","ملف الشركة","الهيكل التنظيمي عند انطباقه"],"verificationNote":"تم استخراج النموذج كاملًا عبر محدد form بعد أن أهمل الاستخراج العام حقوله. يلزم JavaScript لإكماله؛ لم يرسل أي طلب.","applicationUrl":null,"isTender":false,"isSaudiSpecific":true,"evidence":{"officialContentVerified":true,"actionLinkedFromOfficial":true,"actionLandingFetched":true,"formSubmissionTested":false,"method":"TinyFish free search/fetch_content","checkedAt":"2026-10-09T13:13:00Z"},"source_id":"ifas","kind":"supplier_registration","registration_verified":true,"verification_method":"Verified official public extraction; manual import","last_verified":"2026-10-09T13:13:00Z","organization":"IFAS لإدارة المرافق","organization_en":"IFAS","title_en":"IFAS supplier and facility-services registration","description_en":"Actual supplier/service form includes cleaning, security, landscaping, waste, manpower/housekeeping, HVAC/electrical/plumbing/MEP maintenance and civil/fitout works. Qualification and supporting documents are requested; not a specific tender.","source_url":"https://ifas-ksa.com/supplier-portal/","login_required":false,"documents":["السجل التجاري","شهادة ضريبة القيمة المضافة","شهادة البنك والآيبان","عقد التأسيس","القوائم المالية لآخر 3 سنوات","تقرير المشاريع المنجزة وغير المنجزة","تقرير القضايا ونتائجها","خطاب الممثل المفوض مصدقًا من الغرفة التجارية","اتفاقية عدم إفشاء موقعة ومختومة","ملف الشركة","الهيكل التنظيمي عند انطباقه"],"published_at":null,"apply_url":null,"registration_url":"https://ifas-ksa.com/supplier-portal/"}', '2026-10-09T13:13:00Z', '2026-10-10T23:53:28.303Z');
INSERT OR REPLACE INTO opportunities (id, fingerprint, source_id, kind, status, deadline, title, city, organization, data, created_at, updated_at) VALUES ('supplier-ihg', 'bcc2925b668d1a38cead19dc4819190f1fa8eb94abddb2fcd32609468359726b', 'ihg', 'supplier_registration', 'registration_available', NULL, 'إبداء الاهتمام كمورد لسلسلة فنادق IHG — برنامج عالمي', 'عالمي', 'مجموعة فنادق إنتركونتيننتال IHG', '{"id":"supplier-ihg","type":"SUPPLIER_REGISTRATION","title":"إبداء الاهتمام كمورد لسلسلة فنادق IHG — برنامج عالمي","titleEn":"IHG hotel supplier registration — global program","issuer":"مجموعة فنادق إنتركونتيننتال IHG","issuerEn":"IHG Hotels & Resorts","city":"عالمي","country":"GLOBAL","sectors":["hospitality","catering","supplies","maintenance"],"description":"برنامج عالمي لإبداء اهتمام الموردين، وليس عقدًا سعوديًا معلنًا. مجالات الفندق تشمل الغذاء والمشروبات والمستهلكات والهندسة والمرافق. التسجيل لا يضمن RFx أو طلب عرض أو عقد.","descriptionEn":"Global supplier interest program, not an advertised Saudi contract. Hotel procurement covers food, beverage, consumables, engineering and utilities. Registration does not guarantee RFx, request for bid or contract.","sourceUrl":"https://www.ihgplc.com/en/business/suppliers","actionUrl":"https://businessnetwork.gep.com/businessNetwork/directRegistration?bpc=NzAwMjI1Njc1&culture=en-US#/bn-registration-v2","actionType":"register","actionLabel":"تسجيل كمورد","loginRequired":true,"accountRequired":true,"status":"registration_available","deadline":null,"publishedAt":null,"lastVerifiedAt":"2026-10-09T13:13:00Z","sourceStatus":"MANUAL_IMPORT","publicAccess":"LIVE","actionAccess":"DEGRADED","confidence":91,"confidenceScope":"Official page and linked onboarding route verified; form submission, approval and tender invitation not tested.","requiredDocuments":[],"verificationNote":"الرابط الحالي الرسمي إلى GEP وصل بعنوان تسجيل الشبكة؛ استخراج النموذج ناقص. النطاق العالمي ظاهر صراحة ولا يُحسب كمناقصة سعودية.","applicationUrl":null,"isTender":false,"isSaudiSpecific":false,"evidence":{"officialContentVerified":true,"actionLinkedFromOfficial":true,"actionLandingFetched":true,"formSubmissionTested":false,"method":"TinyFish free search/fetch_content","checkedAt":"2026-10-09T13:13:00Z"},"source_id":"ihg","kind":"supplier_registration","registration_verified":true,"verification_method":"Verified official public extraction; manual import","last_verified":"2026-10-09T13:13:00Z","organization":"مجموعة فنادق إنتركونتيننتال IHG","organization_en":"IHG Hotels & Resorts","title_en":"IHG hotel supplier registration — global program","description_en":"Global supplier interest program, not an advertised Saudi contract. Hotel procurement covers food, beverage, consumables, engineering and utilities. Registration does not guarantee RFx, request for bid or contract.","source_url":"https://www.ihgplc.com/en/business/suppliers","login_required":true,"documents":[],"published_at":null,"apply_url":null,"registration_url":"https://businessnetwork.gep.com/businessNetwork/directRegistration?bpc=NzAwMjI1Njc1&culture=en-US#/bn-registration-v2"}', '2026-10-09T13:13:00Z', '2026-10-10T23:53:28.303Z');
INSERT OR REPLACE INTO opportunities (id, fingerprint, source_id, kind, status, deadline, title, city, organization, data, created_at, updated_at) VALUES ('supplier-albawani', 'f11a05346c5fecb8387eca77aa109b316e78d373f5780dc1b574ef05d10fef34', 'albawani', 'supplier_registration', 'registration_available', NULL, 'تسجيل الموردين والمقاولين لدى البواني', 'الرياض', 'البواني القابضة', '{"id":"supplier-albawani","type":"SUPPLIER_REGISTRATION","title":"تسجيل الموردين والمقاولين لدى البواني","titleEn":"Al Bawani supplier and contractor registration","issuer":"البواني القابضة","issuerEn":"Al Bawani Holding","city":"الرياض","country":"SA","sectors":["construction","services"],"description":"بوابة تسجيل الموردين مرتبطة من الموقع الرسمي للبواني. التسجيل يؤهل لإبداء الاهتمام بحسب المنتجات والخدمات المرخصة واحتياج المشتريات؛ ليس دعوة لمقاولة من الباطن أو مناقصة محددة.","descriptionEn":"Vendor onboarding linked by Al Bawani''s official website. Registration supports future interest based on licensed products/services and procurement demand; not an advertised subcontract invitation or specific tender.","sourceUrl":"https://www.albawani.net","actionUrl":"https://s1.ksaprv.cloud.ariba.com/Sourcing/Main/ad/selfRegistration?realm=albawani","actionType":"register","actionLabel":"تسجيل كمورد","loginRequired":true,"accountRequired":true,"status":"registration_available","deadline":null,"publishedAt":null,"lastVerifiedAt":"2026-10-09T13:16:00Z","sourceStatus":"MANUAL_IMPORT","publicAccess":"LIVE","actionAccess":"DEGRADED","confidence":91,"confidenceScope":"Official site supplier registration link and landing redirect verified; interactive form extraction incomplete. No submission or approval tested.","requiredDocuments":[],"verificationNote":"الرابط الرسمي انتقل إلى بوابة Ariba؛ المحتوى المستخرج شاشة تحميل. موقع Vetra يؤكد أن تسجيل الموردين والمقاولين مركزي عبر البواني. لا يضمن دعوة للتنافس.","applicationUrl":null,"isTender":false,"isSaudiSpecific":true,"commercialContacts":[{"type":"email